package com.yuegang.zhihui.common.web;
import feign.*;import feign.codec.ErrorDecoder;import java.time.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.context.annotation.Bean;
@AutoConfiguration public class YghFeignAutoConfiguration{@Bean Request.Options yghFeignOptions(@Value("${ygh.http.connect-timeout:2s}")Duration connect,@Value("${ygh.http.read-timeout:5s}")Duration read){return new Request.Options(connect,read,false);}@Bean ErrorDecoder yghFeignErrorDecoder(){var fallback=new ErrorDecoder.Default();return(method,response)->{var request=response.request();if(request.httpMethod()==Request.HttpMethod.GET&&response.status()>=500)return new RetryableException(response.status(),"Retryable upstream query failure",request.httpMethod(),(Long)null,request);return fallback.decode(method,response);};}@Bean Retryer yghQueryOnlyRetryer(){return new QueryOnlyRetryer(2);}static final class QueryOnlyRetryer implements Retryer{private final int max;private int attempts=1;QueryOnlyRetryer(int max){this.max=max;}public void continueOrPropagate(RetryableException e){if(e.method()!=Request.HttpMethod.GET||attempts++>=max)throw e;try{Thread.sleep(100L*attempts);}catch(InterruptedException x){Thread.currentThread().interrupt();throw e;}}public Retryer clone(){return new QueryOnlyRetryer(max);}}}
